// =============================================================================
// test_MLPREG_torch.cpp
// mc::MLPREG with Torch (MC__USE_TORCH): networks read from TorchScript
// Modules (generated by test_MLP_torch.py) and evaluated by Torch with the
// weights of the operands (Options::EVALTORCH) -- values, Jacobian in the
// inputs and the weights, directional derivatives and adjoints -- against
// the evaluation by MC++, from several threads and through a DAG; and the
// timings of both.
// =============================================================================

#include <chrono>
#include <cmath>
#include <cstdio>
#include <functional>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

#include "interval.hpp"
typedef mc::Interval I;

#include "ffmlpreg.hpp"

typedef mc::MLPREG<I> REG;
using mc::FFGraph;
using mc::FFVar;

static int total = 0, passed = 0, failed = 0;

static double
relerr(std::vector<double> const& a, std::vector<double> const& b)
{
  if (a.size() != b.size()) return INFINITY;
  double e = 0.;
  for (size_t i = 0; i < a.size(); ++i)
    e = std::max(e, std::fabs(a[i] - b[i]) / (1. + std::fabs(b[i])));
  return e;
}

static void
run(std::string const& name, std::function<std::pair<bool, std::string>()> fn)
{
  ++total;
  std::pair<bool, std::string> r;
  try
  {
    r = fn();
  }
  catch (std::exception const& e)
  {
    r = {false, std::string("exception: ") + e.what()};
  }
  ++(r.first ? passed : failed);
  std::printf("  %s  %s%s%s\n", r.first ? "PASS" : "FAIL", name.c_str(),
              r.second.empty() ? "" : " -- ", r.second.c_str());
}

// operands: inputs, then the weights read perturbed by delta
static std::vector<double>
operands(REG const& reg, double const seed, double const delta)
{
  std::vector<double> v(reg.nvar());
  for (size_t i = 0; i < reg.nin(); ++i) v[i] = 0.8 * std::cos(seed + 1.3 * i);
  for (size_t i = 0; i < reg.nwei(); ++i)
    v[reg.nin() + i] = reg.weights()[i] + delta * std::sin(seed + 0.7 * i);
  return v;
}

// values, Jacobian, directional derivative and adjoint, by Torch or by MC++
struct Derivs
{
  std::vector<double> y, J, t, a;
};
static Derivs
derivs(REG& reg, std::vector<double> const& v, bool const torch)
{
  reg.options.EVALTORCH = torch;
  Derivs d;
  size_t const n = reg.nvar(), m = reg.nout();
  d.y.resize(m);
  d.J.resize(m * n);
  d.t.resize(m);
  d.a.resize(n);
  std::vector<double> dir(n), w(m);
  for (size_t i = 0; i < n; ++i) dir[i] = std::cos(0.3 * i);
  for (size_t k = 0; k < m; ++k) w[k] = 1. - 0.4 * k;
  reg.eval(v.data(), d.y.data());
  reg.grad(v.data(), d.J.data());
  reg.tang(v.data(), dir.data(), d.t.data());
  reg.adj(v.data(), w.data(), d.a.data());
  reg.options.EVALTORCH = false;
  return d;
}

static std::string
compare(REG& reg, std::vector<double> const& v, double& err)
{
  Derivs const dt = derivs(reg, v, true), dm = derivs(reg, v, false);
  err = std::max({relerr(dt.y, dm.y), relerr(dt.J, dm.J), relerr(dt.t, dm.t),
                  relerr(dt.a, dm.a)});
  char buf[64];
  std::snprintf(buf, sizeof buf, "relative error %.1e", err);
  return buf;
}

int
main()
{
  std::printf("MLPREG evaluated by Torch\n");
#if !defined(MC__USE_TORCH)
  std::printf("  not run: compiled without Torch (MC__USE_TORCH)\n");
  return 0;
#endif

  for (std::string const name :
       {"torch_tanh.pt", "torch_tanh_double.pt", "torch_two_linear.pt", "torch_out_activ.pt",
        "peak_Tanh_40L4.pt", "peak_ReLU_20L2.pt"})
    run(name + ": values, Jacobian, tangent, adjoint by Torch against MC++", [name]() {
      REG reg;
      if (!reg.read_data(name)) return std::make_pair(false, std::string("not read"));
      double err = 0., e;
      std::string msg;
      for (double delta : {0., 0.05})
      {
        msg = compare(reg, operands(reg, 1. + delta, delta), e);
        err = std::max(err, e);
      }
      char buf[96];
      std::snprintf(buf, sizeof buf, "%zu weights, relative error %.1e", reg.nwei(), err);
      return std::make_pair(err <= 1e-12, std::string(buf));
    });

  run("read: weights of the Module, refusals as for mc::MLP", []() {
    REG reg;
    bool ok = reg.read_data("torch_tanh.pt") && reg.nin() == 2 && reg.nout() == 2 &&
              reg.weights().size() == reg.nwei();
    size_t const uid = reg.uid();
    for (std::string const bad :
         {"torch_leakyrelu.pt", "torch_scaled.pt", "torch_nonet.pt", "torch_missing.pt"})
      ok = ok && !reg.read_data(bad);
    ok = ok && reg.uid() == uid && reg.nin() == 2;
    // a Module with a layer without bias: read, evaluated by MC++
    REG nb;
    ok = ok && nb.read_data("torch_nobias.pt") && nb.nwei() == 5 * 4 + 6 * 2;
    std::vector<double> v = operands(nb, 0.5, 0.1), y1(2), y2(2);
    nb.options.EVALTORCH = true;
    nb.eval(v.data(), y1.data());
    nb.options.EVALTORCH = false;
    nb.eval(v.data(), y2.data());
    return std::make_pair(ok && y1 == y2, std::string());
  });

  run("several threads, each with its copy of the Module and weights of its own", []() {
    REG reg;
    reg.read_data("peak_Tanh_40L4.pt");
    reg.options.EVALTORCH = true;  // the shared MLPREG, evaluated by Torch
    std::vector<int> bad(4, 0);
    std::vector<std::thread> th;
    for (int t = 0; t < 4; ++t)
      th.emplace_back([&, t]() {
        REG mine(reg);  // reference by MC++, a copy for each thread
        mine.options.EVALTORCH = false;
        for (int k = 0; k < 30; ++k)
        {
          std::vector<double> const v = operands(reg, t + 0.1 * k, 0.02);
          std::vector<double> yt(1), ym(1), Jt(reg.nvar()), Jm(reg.nvar());
          reg.eval(v.data(), yt.data());
          reg.grad(v.data(), Jt.data());
          mine.eval(v.data(), ym.data());
          mine.grad(v.data(), Jm.data());
          if (relerr(yt, ym) > 1e-12 || relerr(Jt, Jm) > 1e-12) ++bad[t];
        }
      });
    for (auto& t : th) t.join();
    return std::make_pair(bad == std::vector<int>(4, 0), std::string());
  });

  run("FFMLPREG with EVALTORCH: values and gradient of a training loss", []() {
    REG reg;
    reg.read_data("torch_tanh.pt");
    reg.options.ADJOINT = true;
    FFGraph DAG;
    std::vector<FFVar> W = DAG.add_vars(reg.nwei());
    mc::FFMLPREG<I> Op;
    FFVar L = 0.;
    for (int d = 0; d < 10; ++d)
    {
      double const x0 = -1. + 0.2 * d, x1 = std::cos(x0);
      std::vector<FFVar> Y = Op({FFVar(x0), FFVar(x1)}, W, &reg);
      L += mc::sqr(Y[0] - x0 * x1) + mc::sqr(Y[1] - x0);
    }
    std::vector<FFVar> G = DAG.BAD(std::vector<FFVar>{L}, W);
    G.push_back(L);
    std::vector<double> gm(G.size()), gt(G.size());
    DAG.eval(G, gm, W, reg.weights());
    Op.MLPREG().options.EVALTORCH = true;
    DAG.eval(G, gt, W, reg.weights());
    double const err = relerr(gt, gm);
    char buf[48];
    std::snprintf(buf, sizeof buf, "relative error %.1e", err);
    return std::make_pair(err <= 1e-12, std::string(buf));
  });

  // Timings, microseconds per call
  {
    REG reg;
    if (reg.read_data("torch_wide.pt"))
    {
      std::vector<double> const v = operands(reg, 0.3, 0.);
      std::vector<double> y(reg.nout()), J(reg.nout() * reg.nvar()), a(reg.nvar()),
          w(reg.nout(), 1.);
      auto time = [&](bool const torch, int const what) {
        reg.options.EVALTORCH = torch;
        int const n = (what == 1 ? 20 : 200);
        auto const t0 = std::chrono::steady_clock::now();
        for (int k = 0; k < n; ++k)
          what == 0   ? reg.eval(v.data(), y.data())
          : what == 1 ? reg.grad(v.data(), J.data())
                      : reg.adj(v.data(), w.data(), a.data());
        return std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now() - t0)
                   .count() /
               n;
      };
      std::printf("\n  Timings, %zu inputs, %zu weights, %zu outputs (us): value / Jacobian / adjoint\n",
                  reg.nin(), reg.nwei(), reg.nout());
      for (bool torch : {false, true})
      {
        time(torch, 0);
        std::printf("    %-6s %8.1f %10.1f %8.1f\n", torch ? "Torch" : "MC++", time(torch, 0),
                    time(torch, 1), time(torch, 2));
      }
    }
  }

  std::printf("\n=== Results: %d/%d passed ===\n", passed, total);
  return failed ? 1 : 0;
}
